"use client"
import { useEffect, useState } from 'react';
import ArticleItem from '../components/ArticleItem/ArticleItem';
import articlesInitiaux from '../components/data';
import '../styles/Home.css';

function Home () {
    const [articles, setArticles] = useState([]);
  useEffect(() => {
    const fetchdata = () => {
      const storedArticles = localStorage.getItem('articles');
      (storedArticles && storedArticles.length > 0) ? setArticles(JSON.parse(storedArticles)) : setArticles(articlesInitiaux);

    }
    fetchdata();
    
  }, [])
  
    useEffect(() => { 
      // Sauvegarder les articles dans le localStorage à chaque mise à jour
      localStorage.setItem('articles', JSON.stringify(articles));
    }, [articles]);

  return (
    <div className="home">
      <div className="articles-card">
        <h2>Articles récents</h2>
      <ul>
        {articles.map(article => (
          <ArticleItem key={article.id} article={article} />
        ))}
      </ul>
      </div>
      
      <div className="about">
        <h3>À propos </h3>
        <p>
          Bienvenue sur ce blog dédié aux nouvelles technologies, au développement web et à l’innovation informatique. 
          Ici, je partage des articles, des tutoriels et des réflexions pour aider les passionnés et les professionnels à approfondir leurs connaissances 
          et rester à jour dans un domaine en constante évolution
        </p>
        
      </div>
    </div>
  );
}

export default Home;